def export_to_markdown(content):
    """Export analysis to markdown file."""
    timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    filename = f"adversarial_analysis_pricing_{timestamp}.md"
    filepath = Path(filename)

